.brand .rule {
  width: 1px;
  height: var(--rule-h, 34px);
  background: var(--line);
  flex: none;
}
.brand .event {
  font-size: var(--event-size, 20px);
  font-weight: 650;
  letter-spacing: 0.15em;
  line-height: 1.1;
  white-space: nowrap;
  color: #fff;
}

/* ---------- speaker ---------- */
.speaker {
  display: flex;
  align-items: center;
  gap: var(--sp-gap, 26px);
  flex: none;
}
.avatar {
  width: var(--avatar, 148px);
  height: var(--avatar, 148px);
  flex: none;
  border-radius: 50%;
  overflow: hidden;
  background: #1a1f3d;
  box-shadow: 0 0 0 var(--ring, 4px) var(--accent),
              0 0 0 calc(var(--ring, 4px) + 6px) rgba(124, 92, 255, 0.20);
}
.avatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}
.who { min-width: 0; }
.who .name {
  font-size: var(--name-size, 40px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
  padding-bottom: 0.06em; /* contain descenders / sub-pixel line box */
}
.who .role {
  margin-top: var(--role-gap, 8px);
  font-size: var(--role-size, 22px);
  font-weight: 450;
  line-height: 1.3;
  color: var(--muted);
}

/* ---------- title ---------- */
.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: var(--eyebrow-size, 16px);
  font-weight: 650;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: var(--eyebrow-gap, 18px);
}
.eyebrow::after {
  content: '';
  height: 1px;
  flex: 1;
  background: linear-gradient(to right, rgba(124,92,255,0.5), rgba(124,92,255,0));
}
.title {
  font-size: var(--title-size, 58px);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.025em;
  text-wrap: balance;
}
.title .hl { color: var(--accent); }

/* ---------- meta + cta ---------- */
.foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  flex: none;
}
.meta {
  font-size: var(--meta-size, 23px);
  font-weight: 500;
  line-height: 1.35;
  color: #E7E9F8;
}
.meta .dot { color: var(--accent); padding: 0 6px; }

.cta {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: var(--cta-gap, 12px);
  padding: var(--cta-pad, 18px 34px);
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: var(--cta-size, 22px);
  font-weight: 650;
  letter-spacing: -0.01em;
  line-height: 1;
  white-space: nowrap;
  box-shadow: 0 10px 34px rgba(124, 92, 255, 0.40);
}
.cta svg { width: 1em; height: 1em; display: block; }

.hr {
  height: 1px;
  background: var(--line);
  flex: none;
}

/* =========================================================
   SQUARE 1080 x 1080
   ========================================================= */
body.square .inner {
  flex-direction: column;
  padding: 74px 76px 70px;
  gap: 0;
}
body.square .brand { margin-bottom: 52px; }
body.square .speaker { margin-bottom: 44px; }
body.square .titlewrap { flex: 1 1 auto; display: flex; flex-direction: column; justify-content: center; min-height: 0; }
body.square .hr { margin: 44px 0 36px; }

/* =========================================================
   LANDSCAPE 1920 x 1080
   ========================================================= */
body.landscape .inner {
  flex-direction: row;
  align-items: stretch;
  padding: 80px 96px;
  gap: 92px;
}
body.landscape .left {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
body.landscape .right {
  flex: none;
  width: 648px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  border-left: 1px solid var(--line);
  padding-left: 88px;
}
body.landscape .brand { margin-bottom: 0; }
body.landscape .titlewrap { flex: 1 1 auto; display: flex; flex-direction: column; justify-content: center; min-height: 0; padding: 56px 0; }
body.landscape .right .avatar { margin-bottom: 40px; }
body.landscape .right .who .name { font-size: 46px; white-space: nowrap; }
body.landscape .right .who .role { font-size: 25px; margin-top: 12px; }
body.landscape .right .badge {
  margin-top: 34px;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  border: 1px solid rgba(124,92,255,0.45);
  border-radius: 999px;
  padding: 11px 22px;
  line-height: 1;
}

/* =========================================================
   STORY 1080 x 1920
   ========================================================= */
body.story .inner {
  flex-direction: column;
  padding: 110px 84px 104px;
}
body.story .brand { margin-bottom: 0; }
body.story .speaker {
  flex-direction: column;
  text-align: center;
  align-items: center;
  margin: 0;
}
body.story .speaker .who .name { margin-top: 4px; }
body.story .titlewrap { display: flex; flex-direction: column; justify-content: center; }
body.story .foot { flex-direction: column; align-items: stretch; text-align: center; gap: 36px; }
body.story .cta { align-self: center; }
body.story .spacer { flex: 1 1 auto; min-height: 0; }
